nextflow_process {

    name "Test Process BISCUIT_MERGECG"
    script "../main.nf"
    process "BISCUIT_MERGECG"
    tag "modules"
    tag "modules_nfcore"
    tag "biscuit"
    tag "biscuit/index"
    tag "biscuit/mergecg"

    setup {
            run("BISCUIT_INDEX") {
                script "../../index/main.nf"
                process {
                    """
                    input[0] = Channel.of([
                        [ id:'test' ], // meta map
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                    ])
                    """
                }
            }
        }

    test("sarscov2 cov [bed]") {

        when {
            process {
                """
                input[0] = Channel.of([
                            [ id:'test', single_end:false ], // meta map
                            file(params.modules_testdata_base_path + "delete_me/biscuit/test-cg.bed.gz", checkIfExists: true)
                ])
                input[1] = Channel.of([
                        [ id:'test' ], // meta map
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ])
                input[2] = BISCUIT_INDEX.out.index
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("sarscov2 cov [bed] - stub") {
        options "-stub"

        when {
            process {
                """
                input[0] = Channel.of([
                            [ id:'test', single_end:false ], // meta map
                            file(params.modules_testdata_base_path + "delete_me/biscuit/test-cg.bed.gz", checkIfExists: true)
                ])
                input[1] = Channel.of([
                        [ id:'test' ], // meta map
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ])
                input[2] = BISCUIT_INDEX.out.index
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

}

